    database = db.getdb()
    try:
        covers = database.select('cover', where='archived="'$f and id>7999999 and failed=$f'"', order='id', vars={'f': False}, limit=10000)
        for cover in covers:
            files = {
                'filename': (f'{int(cover.id):010d}.jpg', cover.filename),
                'filename_s': (f'{int(cover.id):010d}-S.jpg', cover.filename_s),
                'filename_m': (f'{int(cover.id):010d}-M.jpg', cover.filename_m),
                'filename_l': (f'{int(cover.id):010d}-L.jpg', cover.filename_l),
            }
            paths = {key: os.path.join(config.data_root, 'localdisk', filename) if filename else None for key, (_, filename) in files.items()}
            if any(path is None or not os.path.exists(path) for path in paths.values()):
                continue
            created = cover.created
            if isinstance(created, str):
                from infogami.infobase import utils
                created = utils.parse_datetime(created)
            timestamp = time.mktime(created.timetuple())
            names = {key: manager.add_file(name, paths[key], timestamp) for key, (name, _) in files.items()}
            if not test:
                database.update('cover', where='id="'$id'"', archived=True, uploaded=False, **names, vars={'id': cover.id})
                for path in paths.values():
                    os.remove(path)
    finally:
        manager.close()


def is_uploaded(item, filename_pattern):
    return Uploader.is_uploaded(item, filename_pattern)


def audit(group_id, chunk_ids=(0, 100), sizes=SIZES):
    scope = range(*(chunk_ids if isinstance(chunk_ids, tuple) else (0, chunk_ids)))
    for size in sizes:
        item = f'{size + \"_\" if size else \"\"}covers_{int(group_id):04d}'
        for batch_id in scope:
            print('.' if Uploader.is_uploaded(item, f'{item}_{batch_id:02d}.zip') else 'X', end='', flush=True)
        print()
